    # The 4-column is a divider. Read the 3x3 colored tiles on its left;
    # the output arranges them as a vertical sequence, with each tile
    # represented in the right-hand 3-column in its displayed orientation.
    # Tile order is scan order (top to bottom, left block then right block).
    h, w = len(grid), len(grid[0])
    div = next((j for j in range(w) if all(grid[i][j] == 4 for i in range(h))), None)
    if div is None:
        return grid
    left = [j for j in range(div) if any(grid[i][j] != 0 for i in range(h))]
    # In this puzzle layout, blocks use columns 0:3 and 4:7.
    blocks = []
    for top in range(0, h, 4):
        if top + 2 >= h:
            continue
        for cols in (range(0, 3), range(4, 7)):
            vals = [grid[r][c] for r in range(top, top+3) for c in cols]
            colors = {v for v in vals if v != 0}
            if len(colors) == 1 and len(vals) == 9:
                color = next(iter(colors))
                # A tile is present only if it has at least one colored cell.
                if color:
                    blocks.append([[grid[r][c] for c in cols] for r in range(top, top+3)])
    # Determine the output tile sequence by locating each 3x3 pattern in
    # the demo-defined order, placing it in a 3-column-wide output canvas.
    # The marked 5 is the anchor, always retained at its original position.
    mark = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 5:
                mark = (r, c)
                break
        if mark:
            break
    # Sort shapes in reading order and transpose pattern positions to output.
    # For the standard 4-block structure, the target is one output row per
    # source tile row; the tiles are drawn as color masks, shifted as directed
    # by the marker's column.
    out_h = h
    out_w = div - 1
    out = [[0 for _ in range(out_w)] for _ in range(out_h)]
    if mark:
        mr, mc = mark
        out[0][min(out_w-1, mc-div)] = 5
    for idx, tile in enumerate(blocks):
        # Tile drawing is determined by the object's color and orientation.
        # Use compressed horizontal mask of each tile, following the examples.
        color = next((v for row in tile for v in row if v), 0)
        # Each source row contributes its colored runs to a vertically stacked
        # output, offset by the local tile row.
        base = idx * 3 + 1
        for rr in range(3):
            for cc in range(3):
                if tile[rr][cc] and base + rr < out_h and cc < out_w:
                    out[base+rr][cc] = color
    return out
